        copyPrompt:
          "(function extractAndDownloadZalo() {\n    const items = [...document.querySelectorAll('.chat-item')];\n\n    const messages = items.map(item => {\n      const nameEl = item.querySelector('.message-sender-name-content');\n      const textEl = item.querySelector('[data-component=\"message-text-content\"]');\n      const qidEl  = item.querySelector('[data-qid]');\n      const imgEl  = item.querySelector('.zavatar img');\n      const timeEl = item.querySelector('.card-send-time__sendTime');\n\n      const qid = qidEl ? qidEl.getAttribute('data-qid') : null;\n      let userId = null, msgId = null, groupId = null;\n      if (qid) {\n        const [userPart, rest] = qid.split('@');\n        const parts = rest ? rest.split('_') : [];\n        userId  = userPart;\n        msgId   = parts[1] || null;\n        groupId = parts[2] || null;\n      }\n\n      return {\n        userId:    userId || '',\n        msgId:     msgId  || '',\n        groupId:   groupId || '',\n        name:      nameEl ? nameEl.innerText.trim() : '',\n        text:      textEl ? textEl.innerText.trim().replace(/\\n/g, ' ') : '',\n        avatarUrl: imgEl  ? imgEl.src : '',\n        time:      timeEl ? timeEl.innerText.trim() : '',\n      };\n    }).filter(m => m.text || m.msgId);\n\n    // Tạo CSV\n    const headers = ['userId','msgId','groupId','name','text','avatarUrl','time'];\n    const escape  = v => '\"' + String(v).replace(/\"/g, '\"\"') + '\"';\n    const rows    = [headers.join(','), ...messages.map(m => headers.map(h => escape(m[h])).join(','))];\n    const csv     = '\\uFEFF' + rows.join('\\r\\n'); // BOM để Excel đọc đúng UTF-8\n\n    // Tự download\n    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });\n    const url  = URL.createObjectURL(blob);\n    const a    = document.createElement('a');\n    a.href     = url;\n    a.download = 'zalo_messages_' + Date.now() + '.csv';\n    document.body.appendChild(a);\n    a.click();\n    document.body.removeChild(a);\n    URL.revokeObjectURL(url);\n\n    console.log(`✅ Đã export ${messages.length} tin nhắn`);\n  })();",
